"""Flujos con SQLite/HTTP real: permisos, conteos, recepciones, surtidos y tránsito."""
import copy,json,uuid
import test_purchase_v3 as purchase_fixture

class InventoryTests(purchase_fixture.PurchaseV3Tests):
 def setUp(self):
  super().setUp();self.w=str(self.company)+':EJIDOS';self.destination=str(self.company)+':SAN PABLO';self.inv('meta');self.sku=self.material['sku']
 def inv(self,path,data=None,actor=None):return self.value('/api/inventarios/'+path,data,actor)
 def state(self,w=None):return self.inv('estado?almacen='+__import__('urllib.parse',fromlist=['quote']).quote(w or self.w))
 def count(self,qty='20',initial=True,w=None,actor=None):
  data={'almacen':w or self.w,'inicial':initial,'filas':[[self.sku,self.material['nombre'],self.material['unidadEntrega'],qty]],'motivo':'Conteo físico','clave':uuid.uuid4().hex};review=self.inv('conteo',{**data,'revisar':True},actor);result=self.inv('conteo',{**data,'huellaActual':review['huellaActual']},actor);return result['solicitud']
 def approve(self,request,actor=None):return self.inv('autorizar',{'id':request['id'],'aprobar':True,'comentario':'Conteo verificado'},actor)
 def activate(self,qty='20',w=None):self.approve(self.count(qty,w=w))
 def amount(self,w=None):return next((r['cantidad'] for r in self.state(w)['existencias'] if r['sku']==self.sku),'0')
 def stockuser(self,role,branches=None):
  branches=branches or (list(__import__('requisiciones').BRANCHES) if role=='gerente' else ['EJIDOS']);email=role+'@inventory.test';self.value('/api/users',{'email':email,'name':role,'role':role,'password':self.password,'active':True,'almacenes':branches,'sucursales':branches});self.po('accesos',{'email':email,'revision':0,'empresas':[self.company],'sucursales':branches});return self.login(email)
 def test_initial_layout_blank_zero_and_approval_roles(self):
  user=self.stockuser('almacenista');req=self.count('0',actor=user);self.assertFalse(self.state()['almacen']['activo']);self.assertEqual(self.call('/api/inventarios/autorizar',{'id':req['id'],'aprobar':True,'comentario':'No autorizado'},user)[0],403);aux=self.stockuser('auxti');self.approve(req,aux);self.assertTrue(self.state()['almacen']['activo']);self.assertEqual(self.amount(),'0')
  bad={'almacen':self.destination,'inicial':True,'filas':[[self.sku,self.material['nombre'],self.material['unidadEntrega'],'']],'revisar':True};self.assertEqual(self.call('/api/inventarios/conteo',bad)[0],400)
  status,data,_=self.call('/api/inventarios/layout?almacen='+self.w);self.assertEqual(status,200);self.assertTrue(data.startswith(b'PK'))
 def test_receipt_and_actual_fulfillment_are_atomic_and_idempotent(self):
  self.activate();doc=self.confirm(self.order());data={'id':doc['id'],'revision':doc['revision'],'clave':uuid.uuid4().hex,'partidas':[{'linea':'1','cantidad':'1'}]};self.po('recepcion',data,self.buyer);self.po('recepcion',data,self.buyer);self.assertEqual(self.amount(),'30');req=self.create_req('5');change={'tipo':'surtir','objetivo':req['id'],'revision':1,'motivo':'Entrega real','datos':{'partidas':[{'materialId':self.material['materialId'],'cantidadSurtida':'3'}]}};self.value('/api/requisiciones/cambios',change);self.assertEqual(self.amount(),'27');self.assertEqual(self.call('/api/requisiciones/cambios',change)[0],409);self.assertEqual(self.amount(),'27')
  current=self.value('/api/requisiciones/'+req['id']);correction={**change,'tipo':'corregir_surtido','revision':current['revision'],'datos':{'partidas':[{'materialId':self.material['materialId'],'cantidadSurtida':'2'}]}};self.value('/api/requisiciones/cambios',correction);self.assertEqual(self.amount(),'28');current=self.value('/api/requisiciones/'+req['id']);self.value('/api/requisiciones/cambios',{'tipo':'cancelar','objetivo':req['id'],'revision':current['revision'],'motivo':'Devuelto'});self.assertEqual(self.amount(),'30')
 def test_insufficient_stock_rolls_back_requisition(self):
  self.activate('1');req=self.create_req('5');status,raw,_=self.call('/api/requisiciones/cambios',{'tipo':'surtir','objetivo':req['id'],'revision':1,'motivo':'Prueba sin físico','datos':{'partidas':[{'materialId':self.material['materialId'],'cantidadSurtida':'3'}]}});self.assertEqual(status,400,raw);self.assertEqual(self.amount(),'1');self.assertEqual(self.value('/api/requisiciones/'+req['id'])['estado'],'SOLICITADA')
 def test_adjustments_require_fresh_count_and_three_approvers(self):
  self.activate();warehouse=self.stockuser('almacenista');request=self.count('15',False,actor=warehouse);self.assertEqual(self.amount(),'20');manager=self.stockuser('gerente');self.approve(request,manager);self.assertEqual(self.amount(),'15');stale=self.count('14',False,actor=warehouse);self.inv('movimiento',{'almacen':self.w,'sku':self.sku,'tipo':'ENTRADA','cantidad':'1','motivo':'Entrada','clave':uuid.uuid4().hex});self.assertEqual(self.call('/api/inventarios/autorizar',{'id':stale['id'],'aprobar':True,'comentario':'Desactualizado'})[0],409);self.assertEqual(self.amount(),'16')
 def test_reset_superadmin_preserves_ledger_and_new_initial_cycle(self):
  self.activate();pending=self.count('19',False);aux=self.stockuser('auxti');self.assertEqual(self.call('/api/inventarios/restablecer',{'almacen':self.w,'revisar':True},aux)[0],403);before=len(self.state()['movimientos']);review=self.inv('restablecer',{'almacen':self.w,'revisar':True});data={'almacen':self.w,'huellaActual':review['huellaActual'],'confirmacion':'RESTABLECER','motivo':'Reinicio autorizado','clave':uuid.uuid4().hex};self.inv('restablecer',data);self.inv('restablecer',data);state=self.state();self.assertEqual(self.amount(),'0');self.assertFalse(state['almacen']['activo']);self.assertEqual(state['almacen']['ciclo'],2);self.assertGreater(len(state['movimientos']),before);self.assertEqual(state['solicitudes'][0]['estado'],'INVALIDADA');self.activate('7');self.assertEqual(self.amount(),'7')
  with self.store.connect() as db:
   with self.assertRaises(__import__('sqlite3').IntegrityError):db.execute('DELETE FROM inv_ledger')
 def test_transfer_transit_partial_arrival_return_and_reset_block(self):
  self.activate();self.activate('0',self.destination);data={'accion':'solicitar','origen':self.w,'destino':self.destination,'partidas':[{'sku':self.sku,'cantidad':'10'}],'motivo':'Reabasto','clave':uuid.uuid4().hex};doc=self.inv('traspaso',data)['traspaso'];self.assertEqual(self.amount(),'20');sent=self.inv('traspaso',{'accion':'enviar','id':doc['id'],'revision':doc['revision'],'persona':'Entrega demo','clave':uuid.uuid4().hex})['traspaso'];self.assertEqual(sent['estado'],'EN_TRANSITO');self.assertEqual(self.amount(),'10');self.assertEqual(self.amount(self.destination),'0');self.assertEqual(sent['costoTransportado'],'100');self.assertEqual(self.call('/api/inventarios/restablecer',{'almacen':self.w,'revisar':True})[0],409)
  received=self.inv('traspaso',{'accion':'recibir','id':sent['id'],'revision':sent['revision'],'persona':'Recibe demo','partidas':[{'sku':self.sku,'cantidad':'6'}],'clave':uuid.uuid4().hex})['traspaso'];self.assertEqual(received['estado'],'PARCIAL');self.assertEqual(self.amount(self.destination),'6');self.assertEqual(self.amount(),'10');returned=self.inv('traspaso',{'accion':'devolver','id':received['id'],'revision':received['revision'],'persona':'Devuelve demo','partidas':[{'sku':self.sku,'cantidad':'4'}],'clave':uuid.uuid4().hex})['traspaso'];self.assertEqual(returned['estado'],'CERRADA_CON_DEVOLUCION');self.assertEqual(self.amount(),'14')
 def test_scope_cost_secrecy_and_reset_old_fulfillment(self):
  warehouse=self.stockuser('almacenista');self.assertEqual(self.call('/api/inventarios/estado?almacen='+__import__('urllib.parse',fromlist=['quote']).quote(self.destination),actor=warehouse)[0],403);requester=self.stockuser('requisicion');self.assertEqual(self.call('/api/inventarios/meta',actor=requester)[0],403);self.activate();req=self.create_req('2');self.value('/api/requisiciones/cambios',{'tipo':'surtir','objetivo':req['id'],'revision':1,'motivo':'Entrega','datos':{'partidas':[{'materialId':self.material['materialId'],'cantidadSurtida':'2'}]}});review=self.inv('restablecer',{'almacen':self.w,'revisar':True});self.inv('restablecer',{'almacen':self.w,'huellaActual':review['huellaActual'],'confirmacion':'RESTABLECER','motivo':'Corte','clave':uuid.uuid4().hex});self.activate();current=self.value('/api/requisiciones/'+req['id']);self.assertEqual(self.call('/api/requisiciones/cambios',{'tipo':'cancelar','objetivo':req['id'],'revision':current['revision'],'motivo':'Otro ciclo'})[0],409)
 def test_four_branches_intercompany_and_destination_only_receiver(self):
  company=self.value('/api/comercial/empresas',{'nombre':'EMPRESA DESTINO','sucursales':list(__import__('requisiciones').BRANCHES)})['id'];destination=str(company)+':EJE 8';meta=self.inv('meta');self.assertEqual(len([w for w in meta['almacenes'] if w['empresa']==company]),4);self.activate();self.activate('0',destination);source_user=self.stockuser('almacenista');data={'accion':'solicitar','origen':self.w,'destino':destination,'partidas':[{'sku':self.sku,'cantidad':'2'}],'motivo':'Intercompañía','clave':uuid.uuid4().hex};doc=self.inv('traspaso',data,source_user)['traspaso'];doc=self.inv('traspaso',{'accion':'enviar','id':doc['id'],'revision':doc['revision'],'persona':'Entrega','clave':uuid.uuid4().hex},source_user)['traspaso'];self.assertTrue(doc['intercompania']);receipt={'accion':'recibir','id':doc['id'],'revision':doc['revision'],'persona':'Recibe','partidas':[{'sku':self.sku,'cantidad':'2'}],'clave':uuid.uuid4().hex};self.assertEqual(self.call('/api/inventarios/traspaso',receipt,source_user)[0],403);self.inv('traspaso',receipt);self.assertEqual(self.amount(destination),'2')

for name in dir(purchase_fixture.PurchaseV3Tests):
 if name.startswith('test_') and name not in InventoryTests.__dict__:setattr(InventoryTests,name,None)
